package com.vocal.security;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import java.nio.charset.StandardCharsets; import java.time.Instant; import java.util.*; import javax.crypto.SecretKey;
@Service public class JwtService { private final SecretKey key; private final long accessMinutes; private final long refreshDays; public JwtService(@Value("${app.jwt.secret}") String secret,@Value("${app.jwt.access-minutes}") long accessMinutes,@Value("${app.jwt.refresh-days}") long refreshDays){this.key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));this.accessMinutes=accessMinutes;this.refreshDays=refreshDays;} public String access(String email, Collection<String> roles){return token(email,roles,accessMinutes*60);} public String refresh(String email){return token(email,List.of("REFRESH"),refreshDays*86400);} private String token(String sub, Collection<String> roles, long seconds){Instant now=Instant.now(); return Jwts.builder().subject(sub).claim("roles",roles).issuedAt(Date.from(now)).expiration(Date.from(now.plusSeconds(seconds))).signWith(key).compact();} public String subject(String token){return Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload().getSubject();}}
